public static void main(String[] args){

  Scanner sc = new Scanner(System.in);

  int h = sc.nextInt();
  int syo = 0;
  int day;

  for(day=0; syo<=h; day++){ // Change the condition to syo<=h to find the first day the plant's height is strictly greater than Takahashi's height
    syo += Math.pow(2, day);
  }
  System.out.println(day);
}

